const ChildComponent = React.memo(({ user }) => { // Note: Added React.memo here!
  console.log('ChildComponent is re-rendering!');
  return <div>User: {user.name}</div>;
});

const ParentComponent = () => {
  const [count, setCount] = useState(0);

  // ✅ SOLUTION: useMemo caches the object reference.
  // The dependency array [] is empty, so this object is created only ONCE.
  const userObject = useMemo(() => ({
    name: 'Alice',
    age: 30
  }), []); // Empty dependency array means it never re-calculates

  return (
    <div>
      <h3>Parent Component</h3>
      <button onClick={() => setCount(c => c + 1)}>
        Re-render Parent (Count: {count})
      </button>
      <hr />
      <ChildComponent user={userObject} />
    </div>
  );
